INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64394779', 64394779, 'analyze_legacy', 'Kab. Kediri', 'kabkota', 'Dinas Pekerjaan Umum dan Penataan Ruang', 'PENGAWASAN KEGIATAN PENGEMBANGAN DAN PENGELOLAAN SISTEM IRIGASI PRIMER DAN SEKUNDER PADA DAERAH IRIGASI YANG LUASNYA DIBAWAH 1000 HA DALAM 1 (SATU) DAERAH KABUPATEN/KOTA ( PAKET 4 ) KABUPATEN KEDIRI TAHUN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'Jawa Timur, Kediri (Kab.)', 64000000, 'April 2026', 'APBD', 1, 1, '1 paket', 'Maksud pengadaan penyediaan jasa konsultansi ini adalah untuk : a. Membantu Satuan Kerja (Satker) Dinas Pekerjaan Umum Dan Penataan Ruang Kabupaten Kediri didalam melakukan pengawasan teknis terhadap kegiatan pekerjaan konstruksi di lapangan yang dilaksanakan oleh Penyedia pekerjaan konstruksi, berhubung adanya keterbatasan tenaga Satuan Kerja yang bersangkutan, baik dari segi jumlah maupun dari segi kualifikasinya. b. Meminimalkan kendala-kendala teknis yang sering dihadapi oleh Penyedia pekerjaan konstruksi di lapangan dalam menerapkan desain yang memenuhi persyaratan spesifikasinya. c. Memberi kepastian dan jaminan kepada Pengguna Jasa bahwa pekerjaan yang dilaksanakan oleh Penyedia pekerjaan konstruksi sesuai dengan spesifikasi dan persyaratan teknis yang tercantum dalam dokumen kontrak. d. Membantu menyelesaikan revisi desain, bilamana terdapat perbedaan antara desain yang ada dengan kondisi dilapangan. Adapun tujuannya adalah pengendalian pelaksanaan pekerjaan di lapangan untuk mendapatkan hasil pekerjaan konstruksi yang memenuhi persyaratan yang tercantum di dalam spesifikasi (tepat mutu), dan dilaksanakan secara tepat biaya serta tepat waktu.', 'a. Melakukan kontrol / Monitoring sehingga terdapat kesesuaian pelaksanaan konstruksi dengan dokumen pelelangan yang dijadikan pedoman, serta peraturan standart dan pedoman teknis yang berlaku. b. Melakukan penelitian dan pengkajian secara mendalam mengenai berbagai aspek dan kemungkinan yang terdapat di lapangan selama masa pelaksanaan konstruksi guna memberikan landasan yang tepat bagi semua pihak yang terkait sebagai dasar pemecahan masalah. c. Melakukan perbaikan terhadap kelemahan-kelemahan yang terjadi dalam pengelolaan, metode kerja, dan pelaksanaan konstruksi.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 310764);
