INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64822362', 64822362, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Penyusunan Analisis Kajian Strategi Sinkronisasi dan Pemetaan Kebijakan Perencanaan Fiskal, Moneter, dan Sektor Keuangan', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 43636364, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '4', 'Adapun tugas dan tanggung jawab sebagai jasa konsultan penyusunan analisis kajian strategi sinkronisasi dan pemetaan kebijakan perencanaan fiskal, moneter dan sektor keuangan sebagai berikut: a. Penyusunan kajian dan identifikasi hambatan implementasi kebijakan aspek fiskal, moneter, dan sektor keuangan; b. Penyusunan kajian evaluasi kebijakan dan strategi sinergi kebijakan sektor keuangan, fiskal dan moneter c. Penyusunan kajian sinergi kebijakan pendanaan prioritas nasional sektor keuangan, fiskal dan moneter pada rancangan awal RKP 2027; d. Penyusunan kajian review kebijakan sektor perbankan, non bank, asuransi, dana pensiun dan pasar modal serta evaluasi sinergi dengan sektor lain dalam sektor keuangan; e. Penyusunan rekomendasi evaluasi capaian kegiatan prioritas sektor keuangan; f. Penyusunan kajian strategi dan pengendalian pembiayaan prioritas fiskal, moneter dan sektor keuangan. g. Penyusunan perumusan rekomendasi penguatan strategi sinergi kebijakan isu sektor keuangan h. Penyusunan rancangan dan rekomendasi akhir penguatan strategi sinergi kebijakan isu sektor keuangan.', 'Adapun syarat dan kualifikasi yang dibutuhkan sebagai adalah sebagai berikut: a. Memiliki latar belakang pendidikan minimal lulusan sarjana (S1) Ilmu Ekonomi; b. Memiliki kompetensi sesuai bidang yang dipersyaratkan dibuktikan dengan ijazah jenjang pendidikan, sertifikat keahlian/teknis, dan/atau sertifikat pelatihan/kursus; c. Memiliki pengalaman paling kurang 2 (dua) tahun terkait analisis sektor keuangan; d. Memiliki pengalaman pekerjaan sejenis (jenis pekerjaan, kompleksitas pekerjaan, metodologi, teknologi, atau karakteristik lainnya yang bisa menggambarkan kesamaan); e. Nilai pekerjaan sejenis tertinggi dalam kurun waktu 10 (sepuluh) tahun terakhir paling kurang sama dengan 50% (lima puluh persen) nilai HPS/Pagu Anggaran; f. Tidak sedang berada dalam kontrak/perjanjian bekerja penuh waktu lain; g. Bersedia bekerja di luar jam kantor dan dalam jadwal ketat; h. Lebih diutamakan memiliki pengalaman dan kemampuan dalam pengembangan serta analisis kebijakan fiskal, moneter, dan sektor keuangan, dapat dibuktikan dengan dokumentasi hasil pekerjaan/tautan hasil pekerjaan; i. Lebih diutamakan pernah melakukan presentasi terkait hasil analisis kebijakan fiskal, moneter dan sektor keuangan di forum publik/internal, dapat dibuktikan dengan dokumentasi hasil pekerjaan/tautan hasil pekerjaan; dan j. Lebih diutamakan pernah bekerjasama dengan Kementerian/Lembaga dapat dibuktikan dengan dokumentasi hasil pekerjaan/tautan hasil pekerjaan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 311084);
