INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64335881', 64335881, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'PAS15 RUTAN KELAS II B KRAKSAAN', 'Belanja Barang ATK untuk Keperluan Perkantoran pada Rumah Tahanan Negara Kelas IIB Kraksaan - Jawa Timur TA 2026', 'Barang', 'E-Purchasing', 'Jawa Timur, Probolinggo (Kab.)', 27000000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, Tahun, @ 27000000 )', '1. ATK ( 1, Tahun, @ 27000000 );', 'Menyediakan barang ATK untuk 1, Tahun, @ 27000000', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 311883);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65369578', 65369578, 'analyze_legacy', 'Kementerian Agraria dan Tata Ruang/BPN', 'central', 'Direktorat Jenderal Tata Ruang', 'Penyusunan Materi Teknis dan Ranperkada RDTR di Kota Bau-Bau', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 4119544000, 'January 2026', 'APBN - PINJAMAN LUAR NEGERI (B)', 1, 1, '2', 'The six (6) main tasks in the formulation of RDTR are interrelated and sequential, as the outputs of each stage or task serve as inputs for the subsequent one. Therefore, the Consultant is required to have a thorough understanding of the workflow in accordance with applicable laws and regulations, as well as technical guidelines related to the preparation of technical materials, Draft Regional Head Regulation (Ranperkada) for the RDTR, and the associated SEA/KLHS. The required steps in the RDTR preparation process are set out in Figure 1 and listed below: Task 1: Preparation Task 2: Data and Information Collection Task 3: Data Processing and Analysis Task 4: Formulation of Concept Plan Task 5: Drafting the Regional Head Regulation of the RDTR for the Regency/City Task 6: Preparation of Requirements for Substantive Approval', 'To achieve spatial planning objectives and targets, the Consultant is to carry out the preparation of RDTR technical materials and the Draft Regional Head Regulation (Ranperkada) through six (6) main tasks in accordance with the Ministerial Regulation of ATR/BPN of 11 of 2021 on Procedures for the Preparation, Review, Revision, and Issuance of Substantive Approval of the Provincial, Regency/City Spatial Planning and Detailed Spatial Planning (RDTR). In addition, each task considers hazard and climate change exposure and vulnerabilities, as well as measures to build resilience over the timeframe of the Plan (i.e., 20 years). The implementation of this activity should follow the project\'s Environmental and Social Management Framework (ESMF), which can be accessed at the following link: https://projects.worldbank.org/en/projects-operations/document-detail/P180860?type=projects The six (6) main tasks in the formulation of RDTR are interrelated and sequential, as the outputs of each stage or task serve as inputs for the subsequent one. Therefore, the Consultant is required to have a thorough understanding of the workflow in accordance with applicable laws and regulations, as well as technical guidelines related to the preparation of technical materials, Draft Regional Head Regulation (Ranperkada) for the RDTR, and the associated SEA/KLHS. The required steps in the RDTR preparation process are set out in Figure 1 and listed below: Task 1: Preparation Task 2: Data and Information Collection Task 3: Data Processing and Analysis Task 4: Formulation of Concept Plan Task 5: Drafting the Regional Head Regulation of the RDTR for the Regency/City Task 6: Preparation of Requirements for Substantive Approval', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 311884);
