INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('64787605', 64787605, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PENGHUBUNG DAN KOORDINASI ANGGOTA FMS', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 85680000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '8', 'Posisi Konsultan Penghubung dan Koordinasi Anggota FMS memiliki Ruang Lingkup sebagai berikut: Menjadi penghubung utama (liaison) antara Sekretariat FMS dan Anggota FMS dalam pelaksanaan kegiatan forum. Melakukan koordinasi komunikasi rutin dengan Anggota FMS terkait agenda, kegiatan, dan kebutuhan forum. Mendukung pengelolaan agenda pertemuan FMS, termasuk penjadwalan, konfirmasi kehadiran, dan penyampaian informasi kegiatan. Menyampaikan bahan diskusi dan informasi kegiatan dari Sekretariat kepada Anggota FMS. Menghimpun masukan, tanggapan, dan saran Anggota FMS sebagai bahan koordinasi internal Sekretariat. Mendukung pelaksanaan forum diskusi, rapat, dan kegiatan FMS dari sisi koordinasi dan komunikasi. Menyusun catatan ringkas hasil pertemuan dan tindak lanjut komunikasi untuk kebutuhan internal. Melakukan pemantauan tindak lanjut komunikasi dan respons Anggota FMS terhadap agenda forum. Berkoordinasi dengan tim Sekretariat FMS untuk memastikan konsistensi informasi dan agenda. Melaksanakan tugas pendukung lainnya yang bersifat koordinatif sesuai arahan Sekretariat FMS, sepanjang tidak mencakup kewenangan administratif ASN.', 'Memiliki pendidikan minimal Sarjana (S1) di bidang Komunikasi atau bidang lain yang relevan dengan analisis ekonomi makro dan pembangunan nasional. Memiliki pengalaman kerja minimal 2 (dua) tahun di bidang analisis ekonomi makro, perencanaan pembangunan, perumusan kebijakan ekonomi, atau penyusunan kajian ekonomi pembangunan, khususnya di lingkungan pemerintahan, lembaga negara, atau institusi kebijakan publik. Bukan berstatus ASN aktif dan tidak sedang terikat kontrak permanen dengan pekerjaan lain; Tidak pernah diberhentikan dengan tidak terhormat sebagai Pegawai/ASN/Konsultan Individu; Diutamakan Konsultan dalam negeri (dibuktikan dengan identitas kewarganegaraan Indonesia seperti Kartu Tanda Penduduk) Mempunyai status valid keterangan Wajib Pajak berdasarkan Hasil Konfirmasi Status Wajib Pajak (KSWP); Memiliki bukti potong pajak atas pengahasilan tertinggi pada institusi/Lembaga pekerjaan sebelumnya atau bukti lapor SPT pajak tahunan terakhir; Memiliki pengalaman berinteraksi dan berkoordinasi dengan berbagai pihak, termasuk instansi pemerintah, organisasi, komunitas, atau forum multipihak. Memiliki kemampuan komunikasi lisan dan tulisan yang sangat baik untuk menyampaikan informasi, agenda, dan bahan kegiatan secara jelas, tepat, dan persuasif. Mampu mengelola komunikasi rutin, termasuk penyampaian undangan, konfirmasi kehadiran, tindak lanjut komunikasi, dan respons terhadap pertanyaan anggota forum. Mampu mengelola agenda kegiatan dan jadwal pertemuan secara tertib dan terkoordinasi. Mampu menyusun catatan ringkas hasil pertemuan, rekap komunikasi, dan daftar tindak lanjut secara sistematis. Memiliki kemampuan koordinasi yang kuat untuk memastikan konsistensi informasi antara Sekretariat dan Anggota FMS. Memiliki keterampilan interpersonal yang baik serta mampu membangun hubungan kerja yang profesional dan kolaboratif. Memiliki integritas, etika kerja, dan sikap profesional dalam menjalankan fungsi penghubung dan koordinasi. Mampu menjaga kerahasiaan data, informasi, dan dokumen strategis yang diperoleh selama pelaksanaan tugas. Tidak sedang menjalani sanksi administratif atau proses hukum serta tidak memiliki konflik kepentingan yang dapat memengaruhi pelaksanaan tugas.Bekerja berdasarkan pendekatan berbasis keluaran (output based) serta memiliki komitmen untuk hadir secara fisik dan melakukan perjalanan dinas apabila dibutuhkan.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 313527);
