INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62929630', 62929630, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'SUKU DINAS CIPTA KARYA, TATA RUANG DAN PERTANAHAN KOTA ADMINISTRASI  JAKARTA SELATAN', 'Pelaksanaan Pengawasan Pemanfaatan  Ruang Senior Assistant Professional Staff -  Planologi/Perencanaan Wilayah dan Kota 2', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 82582500, 'January 2026', 'APBD', 1, 1, '1 Paket', '"Pekerjaan yang dilakukan meliputi: 1. Penyusunan data base hasil monitoring (pengawasan) atas pemanfaatan ruang; 2. Penyusunan data base hasil monitoring (pengawasan) atas konstruksi menara telekomunikasi dan reklame yang berlokasi pada sarana dan prasarana; 3. Melaksanakan pengawasan terhadap pemenuhan kewajiban Surat Izin Penunjukan Penggunaan Tanah (SIPPT) / Izin Penunjukan Penggunaan Tanah (IPPT)/ Izin Prinsip Pemanfaatan Ruang (IPPR); 4. Menyusun bahan evaluasi pemanfaatan prasarana kota meliputi jalan, tata air, ruang terbuka hijau, utilitas dan sarana kota; 5. Penilaian terhadap kesesuaian Peraturan Gubernur Nomor 31 Tahun 2022 tentang Rencana Detail Tata Ruang Wilayah Perencanaan Provinsi DKI Jakarta. "', '"Pekerjaan Senior Assistant Professional Staff di bidang Planologi/Perencanaan Wilayah dan Kota, meliputi: (1) Pendidikan Minimal S1 dari Universitas Negeri/ Swasta; (2) Pengalaman Kerja 0-3 tahun di bidang pemanfaatan dan pengendalian ruang; (3) Menguasai Autocad/Autocad Map, Arc GIS/Arc Map/Arc GIS Pro, Ms. Office, Adobe (Photoshop/InDesign/Illustrator), DropBox/One Box dan menguasai program lain yang menunjang pekerjaan; (4) Memiliki kemampuan pengetahuan, perencanaan dan perancangan tata ruang kota; (5) Mampu bekerja secara individual dan kelompok/tim, siap bekerja di bawah tekanan, diluar jam kerja dan mampu bekerja sesuai arahan; (6) Mampu memaparkan/mempresentasikan setiap tahapan kegiatan; "', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 317129);
